 pair (each attribute's protocol set is tested independently and never leaks to another).

 <p>The check runs against the attribute value as parsed (entities already decoded) rather than against a resolved
 URL: a value such as {@code javascript\:x} is treated as a relative reference by {@link java.net.URL} when a base
 URI is set (or by the internal placeholder base used to preserve relative links), and so would resolve to an
 {@code http(s)} URL and smuggle a dangerous scheme past a prefix-only check.</p>

 <p>Characters that browsers ignore and that have historically disguised schemes — leading, trailing, and embedded
 ASCII controls and whitespace, backslashes, other Unicode whitespace, and Unicode format (zero-width) characters —
 are skipped while reading the scheme, so case changes, padding, control characters, entities, or backslashes can
 not turn a disallowed scheme into an accepted URL.</p>
 */
private boolean isSafeProtocol(Element el, Attribute attr, Set<Protocol> protocols) {
    String value = attr.getValue();

    // fragment references (e.g. "#anchor") are a configuration option, not a URL scheme
    if (isValidAnchor(value))
        return protocolsContain(protocols, AnchorProtocol);

    String scheme = schemeOf(value);
    if (scheme != null) // an explicit scheme is declared; it must be allowed for this exact tag + attribute
        return protocolsContain(protocols, scheme);

    // no scheme declared: a relative, root-relative, or protocol-relative reference, or an unparseable value.
    // Resolve it as before, so that existing relative-link semantics (including the placeholder base) hold.
    String resolved = el.absUrl(attr.getKey());
    if (resolved.isEmpty())
        return false;
    String resolvedScheme = schemeOf(resolved);
    return resolvedScheme != null && protocolsContain(protocols, resolvedScheme);
}

private static boolean protocolsContain(Set<Protocol> protocols, String scheme) {
    String lcScheme = lowerCase(scheme);
    for (Protocol protocol : protocols) {
        if (lcScheme.equals(lowerCase(protocol.toString())))
            return true;
    }
    return false;
}

/**
 Extract the declared URL scheme (RFC 3986: {@code ALPHA *( ALPHA / DIGIT / "+" / "-" / "." ) ":"}) from a raw URL
 value, skipping characters that browsers disregard and that can be used to disguise the scheme (ASCII control
 characters and whitespace, including at the start and end; backslashes; other Unicode whitespace and format
 characters). Returns {@code null} when the value does not declare a scheme (i.e. it is a relative reference) or
 when the bytes before the first colon are not a valid scheme even after normalization, in which case the value is
 handled by the relative-reference path.
 */
static String schemeOf(String value) {
    if (value == null)
        return null;
    int len = value.length();
    int pos = 0;
    while (pos < len && isIgnorableSchemeChar(value.charAt(pos))) // leading padding
        pos++;
    if (pos >= len || !isAsciiAlpha(value.charAt(pos)))
        return null;

    StringBuilder scheme = new StringBuilder();
    while (pos < len) {
        char c = value.charAt(pos);
        if (c == ':')
            return scheme.length() > 0 ? lowerCase(scheme.toString()) : null;
        if (isIgnorableSchemeChar(c) || c == '\\') { // browsers ignore controls/padding; '\' masquerades as '/'
            pos++;
            continue;
        }
        if (!isSchemeChar(c))
            return null; // not a scheme character before the colon: a relative reference
        scheme.append(c);
        pos++;
    }
    return null; // no colon
}

private static boolean isSchemeChar(char c) {
    return isAsciiAlpha(c) || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
}

private static boolean isAsciiAlpha(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

/**
