 whitespace, and Unicode format characters (such as zero-width space and the right-to-left override).
 */
private static boolean isIgnorableSchemeChar(char c) {
    if (c <= ' ' || (c >= 0x7f && c <= 0x9f))
        return true; // C0 controls (incl. HT/LF/CR/FF), DEL, and C1 controls
    if (c == 0xa0 || Character.isWhitespace(c)) // non-breaking space and other Unicode line/space separators
        return true;
    return Character.getType(c) == Character.FORMAT; // zero-width / bidi / other invisible format controls
}

