/**
 Validate a URL-valued attribute against the protocols allowed for this exact tag + attribute pair (each
 attribute's protocol set is tested independently and never leaks to another).
 <p>
 Two checks must both pass:
 </p>
 <ol>
 <li>The scheme declared by the raw, parsed attribute value (HTML entities already decoded) must itself be allowed.
 A value such as {@code javascript\:alert(1)} is a relative reference to {@link java.net.URL}, so against a real
 base URI — or against the placeholder base used to preserve relative links — it resolves to an {@code http(s)}
 URL and would slip past a check that only inspected the resolved URL. The declared scheme is therefore read
 directly from the raw value while skipping characters that browsers ignore and that historically disguise schemes:
 ASCII controls and whitespace (leading, trailing, or embedded), backslashes, other Unicode whitespace, and
 Unicode format characters such as zero-width space. Values that declare no scheme (relative, root-relative, and
 protocol-relative references; bare fragments) declare nothing and so pass this gate.</li>
 <li>The existing resolution-based check still applies, so relative links, anchors, and custom (non-HTTP) protocols
 keep their previous semantics, and hostless {@code http(s)} URLs remain invalid.</li>
 </ol>
 */
private boolean isSafeProtocol(Element el, Attribute attr, Set<Protocol> protocols) {
    String value = attr.getValue();

    // gate 1: if the raw value declares a scheme, that scheme itself must be allowed for this attribute
    String declaredScheme = schemeOf(value);
    if (declaredScheme != null && !protocolsContain(protocols, declaredScheme))
        return false;

    // gate 2: resolve the value (as before) to validate relative links, anchors, custom schemes, and http hosts
    String resolved = getProtocolValue(el, attr);
    for (Protocol protocol : protocols) {
