        Safelist sl = Safelist.basicWithImages()
            .addProtocols("img", "src", "data", "cid")
            .addProtocols("a", "href", "tel", "mailto")
            .preserveRelativeLinks(true);
        String[] vals = {
            "data:text/plain,hi", "DATA:text/plain,hi", "data\\:text/plain,hi",
            "data&colon;text/plain,hi", "&#100;ata:text/plain,hi",
            "cid:1234", "CID:1234", "tel:+1-555", "mailto:&#120;@y.com",
            "javascript:alert(1)", "j%61vascript:alert(1)", "java&#x00;script:1",
            "jAvAsCrIpT&colon;alert(1)", "  javascript:1  ",
            "vbscript:msgbox", "livescript:1", "mocha:1",
            "\u0000javascript:1", "javascript\u0000:1",
            "http://evil.com\\@good.com",
        };
        for (String v : vals) {
            String out = Jsoup.clean("<a href=\"" + v + "\">a</a><img src=\"" + v + "\">", sl);
            System.out.printf("%-32s => %s%n", v.replace("\u0000","<NUL>"), out);
        }
        // double-clean idempotence on a mixed fragment
        String html = "<a href='https://ok.com/x?a=1#f'>k</a><a href='javascript:1'>x</a><a href='/r'>r</a><a href='#h'>h</a>";
        String once = Jsoup.clean(html, sl.addProtocols("a","href","#","https","http"));
        String twice = Jsoup.clean(once, sl.addProtocols("a","href","#","https","http"));
        System.out.println("once : " + once);
        System.out.println("twice: " + twice);
        System.out.println("idempotent: " + once.equals(twice));
    }
}
